test('economy mode disables shadow work without changing source reality root',()=>{const scene=minimalScene(),economy=compileSpatialFrame(scene,{qualityTier:'economy'}),quality=compileSpatialFrame(scene,{qualityTier:'quality'});assert.equal(economy.sourceRealityRoot,quality.sourceRealityRoot);assert.notEqual(economy.frameRoot,quality.frameRoot);assert.equal(economy.passes.some(pass=>pass.kind==='shadow-depth'),false)});
test('frustum culling rejects geometry behind the camera',()=>{const scene=minimalScene();scene.nodes.push({id:'behind',meshId:'cube',materialId:'mat',transform:{translation:[0,0,10]}});const plan=compileSpatialFrame(scene,{width:320,height:180});assert.equal(plan.drawPackets.some(packet=>packet.nodeId==='behind'),false);assert.ok(plan.stats.culledDraws>=1)});
test('parent transforms are applied to child world bounds',()=>{const scene=minimalScene();scene.nodes=[{id:'parent',transform:{translation:[2,0,0]}},{id:'child',parentId:'parent',meshId:'cube',materialId:'mat',transform:{translation:[1,0,0]}}];const plan=compileSpatialFrame(scene);const child=plan.drawPackets.find(packet=>packet.nodeId==='child')!;assert.ok(Math.abs(child.worldBounds.center[0]-3)<1e-9)});
test('distance LOD chooses farther mesh level',()=>{const scene=minimalScene();scene.meshes.push(createCubeMesh('cube-low'));scene.nodes[0]={id:'node',meshId:'cube',materialId:'mat',lods:[{maxDistance:1,meshId:'cube'},{maxDistance:100,meshId:'cube-low'}]};const plan=compileSpatialFrame(scene,{lodBias:1});assert.equal(plan.drawPackets[0]!.meshId,'cube-low');assert.equal(plan.drawPackets[0]!.lodLevel,1)});
test('hierarchical LOD selects a proxy cluster and falls back when the proxy is unavailable',()=>{const scene=minimalScene();scene.meshes.push(createCubeMesh('proxy-mesh',1.5));scene.nodes=[{id:'source:left',meshId:'cube',materialId:'mat',transform:{translation:[-.25,0,0]}},{id:'source:right',meshId:'cube',materialId:'mat',transform:{translation:[.25,0,0]}},{id:'proxy:cluster',meshId:'proxy-mesh',materialId:'mat'}];scene.hlod={clusters:[{id:'cluster:town',sourceNodeIds:['source:left','source:right'],levels:[{maxDistance:4,proxyNodeIds:['proxy:cluster']}]}]};const far=compileSpatialFrame(scene,{width:320,height:180,enableShadows:false,gpuDrivenCulling:true}),farCluster=far.hlod?.clusters[0]!;assert.deepEqual(far.drawPackets.map(packet=>packet.nodeId),['proxy:cluster']);assert.equal(farCluster.selectedLevel,0);assert.deepEqual(farCluster.suppressedNodeIds,['source:left','source:right']);assert.equal(farCluster.proxyAvailable,true);assert.equal(far.stats.hlodProxyDraws,1);assert.equal(far.stats.hlodSuppressedNodes,2);assert.equal(verifySpatialFrame(far).ok,true);const nearScene=clone(scene);nearScene.cameras[0]!.transform.translation=[0,0,3];const near=compileSpatialFrame(nearScene,{width:320,height:180,enableShadows:false,gpuDrivenCulling:true});assert.deepEqual(near.drawPackets[0]!.instances?.map(instance=>instance.nodeId),['source:left','source:right']);assert.equal(near.hlod?.clusters[0]?.selectedLevel,'source');assert.notEqual(far.frameRoot,near.frameRoot);const unavailable=clone(scene);unavailable.nodes.find(node=>node.id==='proxy:cluster')!.visible=false;const fallback=compileSpatialFrame(unavailable,{width:320,height:180,enableShadows:false,gpuDrivenCulling:true});assert.deepEqual(fallback.drawPackets[0]!.instances?.map(instance=>instance.nodeId),['source:left','source:right']);assert.equal(fallback.hlod?.clusters[0]?.selectedLevel,'source');assert.equal(fallback.hlod?.clusters[0]?.proxyAvailable,false);const tampered=clone(far);tampered.hlod!.clusters[0]!.selectedLevel='source';assert.equal(verifySpatialFrame(tampered).ok,false)});
test('automatic HLOD generation creates rooted static proxies under a triangle budget',()=>{const scene=minimalScene(),options={clusterId:'cluster:auto',sourceNodeIds:['node'],levels:[{maxDistance:2,maxTriangles:8},{maxDistance:6,maxTriangles:4}]},first=generateSpatialHLOD(scene,options),second=generateSpatialHLOD(scene,options);assert.equal(first.report.format,'vsr.spatial-hlod-generation.v0.1');assert.equal(first.report.root,second.report.root);assert.equal(first.report.sourceRoot,second.report.sourceRoot);assert.equal(first.generatedMeshes.length,2);assert.equal(first.generatedNodes.length,2);assert.ok(first.generatedMeshes.every(mesh=>mesh.indices.length/3<=8));assert.deepEqual(first.scene.hlod?.clusters[0]?.sourceNodeIds,['node']);assert.equal(first.scene.hlod?.clusters[0]?.levels.length,2);const far=compileSpatialFrame(first.scene,{width:320,height:180,enableShadows:false}),nearScene=clone(first.scene);nearScene.cameras[0]!.transform.translation=[0,0,.5];const near=compileSpatialFrame(nearScene,{width:320,height:180,enableShadows:false});assert.equal(far.hlod?.clusters[0]?.selectedLevel,0);assert.deepEqual(far.hlod?.clusters[0]?.suppressedNodeIds,['node']);assert.equal(far.stats.hlodProxyDraws,1);assert.equal(near.hlod?.clusters[0]?.selectedLevel,'source');assert.equal(verifySpatialFrame(far).ok,true);const animated=clone(scene);animated.nodes[0]!.skinId='missing-skin';assert.throws(()=>generateSpatialHLOD(animated,{sourceNodeIds:['node']}),/static source nodes/);assert.throws(()=>generateSpatialHLOD(scene,{sourceNodeIds:['node'],levels:[{maxDistance:2,maxTriangles:3}]}),/at least 4/) });
test('cell-aware HLOD generation binds proxies to their streaming cells',()=>{const scene=minimalScene();scene.nodes.push({id:'remote',meshId:'cube',materialId:'mat',transform:{translation:[4,0,0]}});scene.streaming={worldId:'world:cell-hlod',cells:[{id:'cell:a',center:[0,0,0],radius:2,nodeIds:['node']},{id:'cell:b',center:[4,0,0],radius:2,nodeIds:['remote']}]};const options={clusterIdPrefix:'world:cell-hlod:auto',levels:[{maxDistance:2,maxTriangles:8},{maxDistance:20,maxTriangles:4}]},first=generateSpatialHLODForStreamingCells(scene,options),second=generateSpatialHLODForStreamingCells(scene,options);assert.equal(first.report.format,'vsr.spatial-hlod-cell-generation.v0.1');assert.equal(first.report.root,second.report.root);assert.equal(first.reports.length,2);assert.equal(first.report.clusters.length,2);for(const entry of first.report.clusters){const cell=first.scene.streaming!.cells.find(candidate=>candidate.id===entry.cellId)!;assert.ok(entry.generatedNodeIds.every(nodeId=>cell.nodeIds.includes(nodeId)))}const far=compileSpatialFrame(first.scene,{width:320,height:180,enableShadows:false,gpuDrivenCulling:true,streaming:{loadRadius:0,unloadRadius:0,forcedCellIds:['cell:a','cell:b']}});assert.equal(far.hlod?.clusters.length,2);assert.ok(far.hlod?.clusters.every(cluster=>cluster.selectedLevel===0&&cluster.proxyAvailable));assert.equal(far.stats.hlodProxyDraws,2);assert.equal(verifySpatialFrame(far).ok,true);const overlap=clone(scene);overlap.streaming!.cells[1]!.nodeIds.push('node');assert.throws(()=>generateSpatialHLODForStreamingCells(overlap,{clusterIdPrefix:'world:cell-hlod:overlap'}),/belongs to both/) });
test('light budget caps visible lights deterministically',()=>{const scene=minimalScene();for(let i=0;i<20;i++)scene.lights.push({id:`point:${i}`,kind:'point',position:[i,2,0],range:5,intensity:1});const plan=compileSpatialFrame(scene,{maxLights:3});assert.equal(plan.lights.length,3);assert.equal(plan.stats.lightCount,3)});
test('GPU light packing keeps ambient separate and bounds dynamic records',()=>{const scene=minimalScene();scene.lights.push({id:'point',kind:'point',position:[2,3,4],range:6,intensity:2,color:'#80cfff'},{id:'directional-2',kind:'directional',direction:[1,-1,0],intensity:.5,castShadow:true});const plan=compileSpatialFrame(scene,{maxLights:8}),packed=packSpatialLightBuffer(plan.lights);assert.equal(packed.byteLength,3*48);assert.equal(packed[0],0);assert.equal(packed[3],1);assert.equal(packed[12],2);assert.equal(packed[13],3);assert.equal(packed[14],4);assert.equal(packed[15],0);assert.ok(Math.abs((packed[16]??0)-128/255)<1e-6);assert.equal(packed[19],2);assert.equal(packed[20],6);assert.equal(packed[21],0);assert.equal(packed[27],1);assert.equal(packed[34],1);const many=Array.from({length:VSR_SPATIAL_MAX_DYNAMIC_LIGHTS+4},(_,index)=>({id:`point:${index}`,kind:'point' as const,position:[index,1,0] as [number,number,number]}));assert.equal(packSpatialLightBuffer(many).byteLength,VSR_SPATIAL_MAX_DYNAMIC_LIGHTS*48)});
