test('WGSL modules expose real vertex fragment shadow deformation and irradiance volume stages',()=>{assert.match(VSR_SPATIAL_VERTEX_WGSL_V04,/@vertex fn vs_main/);assert.match(VSR_SPATIAL_VERTEX_WGSL_V04,/jointMatrices/);assert.match(VSR_SPATIAL_VERTEX_WGSL_V04,/morphDeltas/);assert.match(VSR_SPATIAL_FRAGMENT_WGSL_V04,/@fragment fn fs_main/);assert.match(VSR_SPATIAL_FRAGMENT_WGSL_V04,/spatialLights/);assert.match(VSR_SPATIAL_FRAGMENT_WGSL_V04,/arrayLength/);assert.match(VSR_SPATIAL_FRAGMENT_WGSL_V04,/environmentVolume/);assert.match(VSR_SPATIAL_FRAGMENT_WGSL_V04,/environmentVolumeSample/);assert.match(VSR_SPATIAL_SHADOW_WGSL_V04,/@vertex fn vs_shadow/);assert.match(VSR_SPATIAL_SHADOW_WGSL_V04,/skinPosition/) });
test('dynamic irradiance volume bakes trilinear samples and updates from changed lights',()=>{const scene=minimalScene();scene.environment={diffuseColor:'#17233b',specularColor:'#8fb8e8',intensity:.35};const options={dimensions:[3,2,3] as [number,number,number],visibilitySamples:4,shadowBias:.001,updateAlpha:.5},first=bakeSpatialIrradianceVolume(scene,options),repeat=bakeSpatialIrradianceVolume(scene,options),persisted=structuredClone(first);assert.equal(first.root,repeat.root);assert.equal(verifySpatialIrradianceVolume(persisted).ok,true);assert.equal(first.samples.length,18);assert.equal(packSpatialIrradianceVolumeBuffer(first).byteLength,640);const sample=sampleSpatialIrradianceVolume(first,[0,0,0],[0,0,0],[0,0,0]);assert.ok(sample.diffuse.some(value=>value>0));const bakedScene=applySpatialIrradianceVolume(scene,persisted),base=renderSpatialReference(scene,{width:160,height:90,enableShadows:false}),baked=renderSpatialReference(bakedScene,{width:160,height:90,enableShadows:false});assert.equal(baked.framePlan.environment.irradianceVolumeBakeRoot,first.root);assert.equal(baked.framePlan.environment.irradianceVolume?.samples.length,18);assert.equal(baked.framePlan.resources.find(resource=>resource.id==='environment-volume')?.kind,'environment-volume-buffer');assert.notEqual(baked.pixelRoot,base.pixelRoot);const changed=structuredClone(scene);changed.lights[1]!.intensity=3;const updated=updateSpatialIrradianceVolume(changed,first,{updateAlpha:1});assert.equal(updated.topologyRoot,first.topologyRoot);assert.notEqual(updated.sourceRoot,first.sourceRoot);assert.notEqual(updated.root,first.root);assert.notDeepEqual(updated.samples,first.samples);assert.equal(verifySpatialIrradianceVolume(updated).ok,true);const updatedScene=applySpatialIrradianceVolume(changed,updated),updatedRender=renderSpatialReference(updatedScene,{width:160,height:90,enableShadows:false});assert.equal(updatedRender.framePlan.environment.irradianceVolumeBakeRoot,updated.root);assert.notEqual(updatedRender.pixelRoot,baked.pixelRoot)});
test('multi-volume irradiance field blends cells and updates active GPU resources',()=>{const scene=minimalScene();scene.environment={diffuseColor:'#17233b',specularColor:'#8fb8e8',intensity:.35};scene.streaming={worldId:'world:minimal',cells:[{id:'cell:left',center:[-2,0,0],radius:4,nodeIds:['node']},{id:'cell:right',center:[20,0,0],radius:4,nodeIds:['node']} ]};const leftMin=[-4,-2,-2] as [number,number,number],leftMax=[0,2,2] as [number,number,number],rightMin=[16,-2,-2] as [number,number,number],rightMax=[24,2,2] as [number,number,number],options={blendDistance:1,maxSamples:128,volumes:[{id:'left',cellId:'cell:left',boundsMin:leftMin,boundsMax:leftMax,dimensions:[3,2,3] as [number,number,number],visibilitySamples:2,shadowBias:.001},{id:'right',cellId:'cell:right',boundsMin:rightMin,boundsMax:rightMax,dimensions:[3,2,3] as [number,number,number],visibilitySamples:2,shadowBias:.001}]},field=bakeSpatialIrradianceVolumeField(scene,options),repeat=bakeSpatialIrradianceVolumeField(scene,options);assert.equal(field.root,repeat.root);assert.equal(field.volumes.length,2);assert.equal(field.volumes.reduce((sum,entry)=>sum+entry.volume.samples.length,0),36);assert.equal(verifySpatialIrradianceVolumeField(structuredClone(field)).ok,true);assert.equal(packSpatialIrradianceVolumeFieldBuffer(field).byteLength,1296);const fieldSample=sampleSpatialIrradianceVolumeField(field,[0,0,0],[0,0,0],[0,0,0]);assert.ok(fieldSample.diffuse.some(value=>value>0));const fieldScene=applySpatialIrradianceVolumeField(scene,field),both=compileSpatialFrame(fieldScene,{width:160,height:90,enableShadows:false,streaming:{loadRadius:0,unloadRadius:0,forcedCellIds:['cell:left','cell:right']}}),left=compileSpatialFrame(fieldScene,{width:160,height:90,enableShadows:false,streaming:{loadRadius:0,unloadRadius:0,forcedCellIds:['cell:left']}}),none=compileSpatialFrame(fieldScene,{width:160,height:90,enableShadows:false,streaming:{loadRadius:0,unloadRadius:0,forcedCellIds:[]}});assert.equal(both.environment.irradianceVolumeField?.volumes.length,2);assert.equal(left.environment.irradianceVolumeField?.volumes.length,1);assert.equal(left.environment.irradianceVolumeField?.volumes[0]!.id,'left');assert.equal(none.environment.irradianceVolumeField,undefined);assert.equal(verifySpatialFrame(none).ok,true);assert.notEqual(left.environment.irradianceVolumeFieldRoot,field.root);assert.equal(verifySpatialFrame(left).ok,true);const tamperedLeft=structuredClone(left);tamperedLeft.environment.irradianceVolumeField!.root='0'.repeat(64);assert.equal(verifySpatialFrame(tamperedLeft).ok,false);assert.equal(both.resources.find(resource=>resource.id==='environment-volume')?.byteLength,packSpatialIrradianceVolumeFieldBuffer(both.environment).byteLength);const base=renderSpatialReference(scene,{width:160,height:90,enableShadows:false}),rendered=renderSpatialReference(fieldScene,{width:160,height:90,enableShadows:false});assert.equal(rendered.framePlan.environment.irradianceVolumeFieldRoot,field.root);assert.notEqual(rendered.pixelRoot,base.pixelRoot);const changed=clone(scene);changed.lights[1]!.intensity=3;const updated=updateSpatialIrradianceVolumeField(changed,field,{updateAlpha:1});assert.equal(updated.topologyRoot,field.topologyRoot);assert.notEqual(updated.sourceRoot,field.sourceRoot);assert.notEqual(updated.root,field.root);assert.equal(verifySpatialIrradianceVolumeField(updated).ok,true);assert.notEqual(renderSpatialReference(applySpatialIrradianceVolumeField(changed,updated),{width:160,height:90,enableShadows:false}).pixelRoot,rendered.pixelRoot)});
test('reference renderer emits deterministic real PNG pixels',()=>{const scene=createSpatialShowcaseScene(),a=renderSpatialReference(scene,{width:320,height:180,shadowMapSize:128}),b=renderSpatialReference(scene,{width:320,height:180,shadowMapSize:128});assert.ok(a.png.byteLength>1000);assert.deepEqual([...a.png.slice(0,8)],[137,80,78,71,13,10,26,10]);assert.equal(a.pixelRoot,b.pixelRoot);assert.ok(a.depthRange.min<a.depthRange.max)});
